/**
 * The ordered root stage pipeline (M-A2): wrapper stacks the flat row-root parser cannot represent — notably
 * {@code Slice(Order(Slice(...)))}, which no parsed SPARQL query produces but programmatic algebra construction does —
 * compile as generic modifier stages in exact algebra order over a native inner root, instead of declining the whole
 * root to the generic host.
 */
public class LmdbNativeRootPipelineTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			ValueFactory vf = conn.getValueFactory();
			IRI p = vf.createIRI(EX, "p");
			conn.add(vf.createIRI(EX, "s1"), p, vf.createLiteral("delta"));
			conn.add(vf.createIRI(EX, "s2"), p, vf.createLiteral("alpha"));
			conn.add(vf.createIRI(EX, "s3"), p, vf.createLiteral("charlie"));
			conn.add(vf.createIRI(EX, "s4"), p, vf.createLiteral("bravo"));
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	/**
	 * Builds {@code Slice(limit=innerLimit, Order(?o asc, Slice(limit=outerFirstLimit, Projection(?s ?o))))} — a
	 * wrapper stack no parsed query produces (two slices around one order): the algebra the umbrella plan's "a flat
	 * record cannot represent Slice(Order(Slice(…)))" refers to.
	 */
	private TupleExpr sliceOrderSlice(long innerSliceLimit, long outerSliceLimit) {
		TupleExpr parsed = QueryParserUtil
				.parseTupleQuery(QueryLanguage.SPARQL, "SELECT ?s ?o WHERE { ?s <" + EX + "p> ?o }", null)
				.getTupleExpr();
		TupleExpr projection = parsed instanceof QueryRoot ? ((QueryRoot) parsed).getArg() : parsed;
		projection = projection.clone();
		Slice innerSlice = new Slice(projection);
		innerSlice.setLimit(innerSliceLimit);
		Order order = new Order(innerSlice);
		order.addElement(new OrderElem(new Var("o"), true));
		Slice outerSlice = new Slice(order);
		outerSlice.setLimit(outerSliceLimit);
		return new QueryRoot(outerSlice);
	}

	private List<String> evaluate(TupleExpr algebra) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			SailConnection sail = conn.getSailConnection();
			List<String> rows = new ArrayList<>();
			try (CloseableIteration<? extends BindingSet> iteration = sail.evaluate(algebra, new SimpleDataset(),
					EmptyBindingSet.getInstance(), true)) {
				while (iteration.hasNext()) {
					BindingSet bs = iteration.next();
					rows.add(bs.getValue("o") == null ? "unbound" : bs.getValue("o").stringValue());
				}
			}
			return rows;
		}
	}

	/** The unrepresentable stack compiles as a pipeline root and keeps both slices in exact algebra order. */
	@Test
	public void sliceOrderSliceCompilesAsPipelineAndKeepsBothSlices() {
		withProperty(NativeRootPipeline.ENABLED_FLAG, "true", () -> {
			long pipelinesBefore = LmdbNativeAggregateCompiler.PIPELINE_ROOTS.get();
			List<String> nativeRows = evaluate(sliceOrderSlice(10L, 2L));
			assertThat(LmdbNativeAggregateCompiler.PIPELINE_ROOTS.get() - pipelinesBefore)
					.as("the unrepresentable wrapper stack must compile as a pipeline root")
					.isEqualTo(1);
			List<String> genericRows = withNativeOff(() -> evaluate(sliceOrderSlice(10L, 2L)));
			assertThat(nativeRows).isEqualTo(genericRows);
			assertThat(nativeRows).hasSize(2);
		});
	}

	/** M-F6 rollout: the root stage pipeline is on by default — it engages with no flag set at all. */
	@Test
	public void pipelineEngagesByDefault() {
		String previous = System.getProperty(NativeRootPipeline.ENABLED_FLAG);
		System.clearProperty(NativeRootPipeline.ENABLED_FLAG);
		try {
			long pipelinesBefore = LmdbNativeAggregateCompiler.PIPELINE_ROOTS.get();
			List<String> nativeRows = evaluate(sliceOrderSlice(10L, 2L));
			assertThat(LmdbNativeAggregateCompiler.PIPELINE_ROOTS.get() - pipelinesBefore)
					.as("the root stage pipeline must engage by default (M-F6 rollout)")
					.isEqualTo(1);
			assertThat(nativeRows).isEqualTo(withNativeOff(() -> evaluate(sliceOrderSlice(10L, 2L))));
		} finally {
			if (previous != null) {
				System.setProperty(NativeRootPipeline.ENABLED_FLAG, previous);
			}
		}
	}

	/** Pipeline off: the stack is hosted generically, results identical — the kill switch only moves the engine. */
	@Test
	public void pipelineDisabledStaysHostedAndCorrect() {
		withProperty(NativeRootPipeline.ENABLED_FLAG, "false", () -> {
			long pipelinesBefore = LmdbNativeAggregateCompiler.PIPELINE_ROOTS.get();
			List<String> nativeRows = evaluate(sliceOrderSlice(10L, 2L));
			assertThat(LmdbNativeAggregateCompiler.PIPELINE_ROOTS.get() - pipelinesBefore).isZero();
			assertThat(nativeRows).isEqualTo(withNativeOff(() -> evaluate(sliceOrderSlice(10L, 2L))));
		});
	}

	/** Distinct stacked over the unrepresentable stack: stage order preserved, generic-equal. */
	@Test
	public void distinctOverPipelineStackIsExact() {
		withProperty(NativeRootPipeline.ENABLED_FLAG, "true", () -> {
			TupleExpr algebra = sliceOrderSlice(4L, 4L);
			TupleExpr inner = ((QueryRoot) algebra).getArg();
			org.eclipse.rdf4j.query.algebra.Distinct distinct = new org.eclipse.rdf4j.query.algebra.Distinct(inner);
			TupleExpr root = new QueryRoot(distinct);
			List<String> nativeRows = evaluate(root);
			TupleExpr algebra2 = sliceOrderSlice(4L, 4L);
			TupleExpr root2 = new QueryRoot(
					new org.eclipse.rdf4j.query.algebra.Distinct(((QueryRoot) algebra2).getArg()));
			assertThat(nativeRows).isEqualTo(withNativeOff(() -> evaluate(root2)));
		});
	}

	/**
	 * M-A2 nested roots: an island whose body is a supported subquery Projection claims a nested native root (its own
	 * private slot layout) instead of evaluating generically — pinned via the native-claim counter.
	 */
	@Test
	public void islandSubqueryBodyClaimsNestedNativeRoot() {
		String query = "SELECT ?s ?o WHERE { ?s <" + EX + "p> ?o . "
				+ "{ SELECT ?s WHERE { ?s <" + EX + "p> ?any } LIMIT 10 } }";
		withProperty("rdf4j.lmdb.islands.enabled", "true", () -> {
			long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
			try (SailRepositoryConnection conn = repository.getConnection()) {
				List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
				assertThat(rows).hasSize(4);
			}
			assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
					.as("outer row root + nested native claim of the subquery island body")
					.isGreaterThanOrEqualTo(2);
		});
	}

	/** ASK over an unsupported root stays hosted and correct. */
	@Test
	public void askOverUnsupportedRootIsHostedAndCorrect() {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			boolean result = conn
					.prepareBooleanQuery(QueryLanguage.SPARQL,
							"ASK { ?s <" + EX + "p> ?o FILTER(STRLEN(LCASE(?o)) > 0) }")
					.evaluate();
			assertThat(result).isTrue();
		}
	}

	private List<String> withNativeOff(java.util.function.Supplier<List<String>> action) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, "false");
			return action.get();
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private void withProperty(String name, String value, Runnable action) {
		String previous = System.getProperty(name);
		try {
			System.setProperty(name, value);
			action.run();
		} finally {
			if (previous == null) {
				System.clearProperty(name);
			} else {
				System.setProperty(name, previous);
			}
		}
	}
}
